-- =============================================================================
-- SCRIPT DE RESTAURACIÓN DE VACANTES ELIMINADAS
-- =============================================================================
-- Restaura las 34 vacantes que fueron eliminadas incorrectamente
-- (vacantes con códigos que terminaban en 'a' o 'b' u otros)
-- TOTAL DE APLICACIONES AFECTADAS: 131
-- =============================================================================

START TRANSACTION;
SET FOREIGN_KEY_CHECKS = 0;

-- Insertar las 34 vacantes eliminadas

SET FOREIGN_KEY_CHECKS = 1;

-- Verificar restauración
SELECT id, code, title FROM kjrt_local_jobboard_vacancy 
WHERE id IN (749,750,757,758,759,760,761,762,763,764,765,766,767,768,769,770,771,772,773,774,775,776,777,778,779,780,781,782,783,784,785,786,787,788);

COMMIT;

